import { PlaneGeometry, Mesh, Vector3 } from 'three/webgpu';
import {
  texture, uniform, add, mul, vec2, vec3, float, positionGeometry, normalGeometry,
  displacement, MeshStandardNodeMaterial
} from 'three/tsl';
import gsap from 'gsap';
import { AtlasTexture } from '@/text';

export default function createNode(config, ctx) {
  const { assets, visual, behavior, position, rotation, scale, cinematicPrimitives, atlasRegion } = config;

  // Load textures
  const colorTex = ctx.textureLoader.load(assets.imageUrl);
  const depthTex = ctx.textureLoader.load(assets.depthMapUrl);

  // Plane dimensions derived from atlas aspect ratio (512x320 → 1.6:1)
  const planeWidth = 2.5;
  const planeHeight = planeWidth * (320 / 512);

  // Tessellated geometry
  const geometry = new PlaneGeometry(planeWidth, planeHeight, 64, 64);
  geometry.rotateX(-Math.PI / 2); // Layout flat in scene space

  // Displacement node using depth map
  const depthMap = texture(depthTex);
  const dispStrength = uniform(0.02); // subtle displacement
  const dispOffset = mul(depthMap.r, dispStrength);
  const displacedPos = add(positionGeometry, mul(normalGeometry, dispOffset));

  // Material with displacement
  const material = new MeshStandardNodeMaterial();
  material.colorNode = texture(colorTex);
  material.positionNode = displacedPos;
  material.metalness = 0.55;
  material.roughness = 0.5;
  material.clearcoat = 0.25;
  material.anisotropy = 0.5;
  material.side = 0; // DoubleSide? but default is front

  const mesh = new Mesh(geometry, material);
  mesh.position.set(position.x, position.y, position.z);
  mesh.rotation.set(rotation.x, rotation.y, rotation.z);
  mesh.scale.set(scale.x, scale.y, scale.z);

  // userData
  mesh.userData = mesh.userData || {};
  mesh.userData.handlers = {};

  // Weighted-settle entrance
  const entranceTimeline = gsap.timeline();
  entranceTimeline.fromTo(mesh.scale, { x: 1.04, y: 1.04, z: 1.04 }, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
    overwrite: 'auto'
  });

  // Hover handler: rise-in preset with 0.15 offset
  const origY = mesh.position.y;
  let hoverTween = null;

  mesh.userData.handlers.mouseenter = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: origY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
      overwrite: 'auto'
    });
  };

  mesh.userData.handlers.mouseleave = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(mesh.position, {
      y: origY,
      duration: 0.7,
      ease: 'power3.out',
      overwrite: 'auto'
    });
  };

  // Click handler: emit hub-home.select
  mesh.userData.handlers.click = () => {
    if (config.behavior?.interactions?.find(i => i.event === 'click')) {
      mesh.dispatchEvent({ type: 'hub-home.select' });
    }
  };

  // Apply cinematic primitives
  cinematicPrimitives.forEach(primitive => {
    const fn = ctx.primitives[primitive.name];
    if (fn) {
      fn(mesh, primitive.params);
    }
  });

  // Cleanup
  mesh.userData.cleanup = () => {
    entranceTimeline.kill();
    if (hoverTween) hoverTween.kill();
    geometry.dispose();
    material.dispose();
    colorTex.dispose();
    depthTex.dispose();
  };

  return mesh;
}
